using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using TutorialFramework;
[DefaultExecutionOrder(10000)]public class CameraMouseProbe:MonoBehaviour{
 public bool done;public string result;public SmoothCameraMovement mover;public bool guided;static BindingFlags flags=BindingFlags.Instance|BindingFlags.NonPublic;int stage;float duration;Camera cameraView;Vector2 mouse;Vector3 origin;Quaternion rotation;float fov;List<Transform> views;
 object Get(string n)=>typeof(SmoothCameraMovement).GetField(n,flags).GetValue(mover);void Set(string n,object v)=>typeof(SmoothCameraMovement).GetField(n,flags).SetValue(mover,v);void Check(bool yes,string message){if(!yes)throw new Exception(message);}bool UI(Vector2 p)=>(bool)typeof(SmoothCameraMovement).GetMethod("IsPointerOverUI",flags).Invoke(mover,new object[]{p});void InputAt(Vector2 p,bool down=false,bool held=false,float scroll=0,bool over=false)=>typeof(SmoothCameraMovement).GetMethod("ProcessMouseNavigation",flags).Invoke(mover,new object[]{p,down,held,scroll,over});void Request(int index){var p=mover.transform.position;var r=mover.transform.rotation;mover.MoveToPosition(index);Check(mover.transform.position==p&&mover.transform.rotation==r,"View request moved camera outside LateUpdate");}
 public void Begin(SmoothCameraMovement m,bool g){mover=m;guided=g;cameraView=m.GetComponent<Camera>();duration=(float)Get("moveDuration");views=(List<Transform>)Get("cameraPositions");Set("moveDuration",0f);Request(11);}
 Vector2 FindScenePoint(){var rect=cameraView.pixelRect;foreach(float x in new[]{.2f,.4f,.6f,.8f})foreach(float y in new[]{.25f,.4f,.6f,.75f}){var p=new Vector2(rect.x+x*rect.width,rect.y+y*rect.height);if(!UI(p))return p;}throw new Exception("No scene area accepts navigation; UI blocks entire screen");}
 void Pan(Vector2 start,Vector2 delta){InputAt(start,true,true);InputAt(start+delta,false,true);}
 void LateUpdate(){if(done||!mover)return;try{if(stage==0){Check(Vector3.Distance(mover.transform.position,views[11].position)<.001f,"Wrong initial view");mouse=FindScenePoint();origin=mover.transform.position;rotation=mover.transform.rotation;fov=cameraView.fieldOfView;
 Pan(mouse,new Vector2(45,35));Check((Vector3.Distance(origin,mover.transform.position)>.001f)==!guided,"Wrong pan mode gate");Check(Quaternion.Angle(rotation,mover.transform.rotation)<.001f,"Pan rotated camera");float before=cameraView.fieldOfView;InputAt(mouse,scroll:1);Check(guided?cameraView.fieldOfView==before:cameraView.fieldOfView<before,"Wrong view 11 zoom gate");
 if(!guided){InputAt(mouse,scroll:1000);Check(cameraView.fieldOfView==20,"Minimum zoom bound");InputAt(mouse,scroll:-1000);Check(cameraView.fieldOfView==80,"Maximum zoom bound");for(int i=0;i<10;i++)Pan(new Vector2(cameraView.pixelRect.width*.2f,cameraView.pixelRect.height*.2f),new Vector2(cameraView.pixelRect.width*.6f,cameraView.pixelRect.height*.6f));Check(Vector3.Distance(origin,mover.transform.position)<=25.001f,"Pan limit exceeded");}
 var button=SceneManager.GetActiveScene().GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).Single(t=>t.name=="Wind Speed Button");var buttonPoint=RectTransformUtility.WorldToScreenPoint(null,button.position);Check(UI(buttonPoint),"Actual UI button not detected by UI guard");var saved=mover.transform.position;before=cameraView.fieldOfView;InputAt(buttonPoint,true,true,1,UI(buttonPoint));Check(mover.transform.position==saved&&cameraView.fieldOfView==before,"UI drag/wheel moved camera");InputAt(mouse+Vector2.one*30,false,true);Check(mover.transform.position==saved,"Drag resumed after crossing UI");
 Pan(mouse,Vector2.one*5);typeof(SmoothCameraMovement).GetMethod("OnApplicationFocus",flags).Invoke(mover,new object[]{false});saved=mover.transform.position;InputAt(mouse+Vector2.one*50,false,true);Check(mover.transform.position==saved,"Drag resumed after focus loss");Request(12);saved=mover.transform.position;before=cameraView.fieldOfView;InputAt(mouse,true,true,1);Check(mover.transform.position==saved&&cameraView.fieldOfView==before,"Input interrupted a view transition");stage=1;return;}
 if(stage==1){Check(Vector3.Distance(mover.transform.position,views[12].position)<.001f&&cameraView.fieldOfView==fov,"Saved view did not reset pan/zoom");origin=mover.transform.position;mouse=FindScenePoint();InputAt(mouse,scroll:1);Check(cameraView.fieldOfView<fov,"View 12 zoom missing");Pan(mouse,new Vector2(40,30));Check((Vector3.Distance(origin,mover.transform.position)>.001f)==!guided,"Guided monitor panning unlocked");InputAt(mouse,scroll:1000);Check(cameraView.fieldOfView==20,"Monitor min zoom");InputAt(mouse,scroll:-1000);Check(cameraView.fieldOfView==80,"Monitor max zoom");Request(0);stage=2;return;}
 if(stage==2){Check(Vector3.Distance(mover.transform.position,views[0].position)<.001f&&cameraView.fieldOfView==fov,"Overview did not restore original pose/lens");float before=cameraView.fieldOfView;InputAt(FindScenePoint(),scroll:1);Check(guided?cameraView.fieldOfView==before:cameraView.fieldOfView<before,"Zoom mode gate wrong after leaving monitor");Set("moveDuration",duration);result="PASS: "+(guided?"Guided view 12 zoom only":"Free pan/zoom")+", saved-view reset, UI guard, bounds, focus/release guards, rotation preserved, LateUpdate requests.";done=true;}
 }catch(Exception e){Set("moveDuration",duration);result="FAIL "+e;done=true;}}
}
[InitializeOnLoad]public static class CameraMouseTest{
 const string P="CameraMouseTest.";static readonly string[] ids={"Speed Curve Characteristics","Regulating DC Output from Wind Turbine using PWM Charger","Regulating DC Output from Wind Turbine using MPPT Charger","OFF Grid System Using Wind Turbine"};static bool Run{get=>SessionState.GetBool(P+"run",false);set=>SessionState.SetBool(P+"run",value);}static int Stage{get=>SessionState.GetInt(P+"stage",0);set=>SessionState.SetInt(P+"stage",value);}static int Index{get=>SessionState.GetInt(P+"index",0);set=>SessionState.SetInt(P+"index",value);}static double Due{get=>SessionState.GetFloat(P+"due",0);set=>SessionState.SetFloat(P+"due",(float)value);}static bool Guided=>SessionState.GetBool(P+"guided",false);static string Report=>"Temp/CameraMouseNavigation/"+(Guided?"52-guided":"42-free")+".txt";static CameraMouseProbe probe;
 static CameraMouseTest(){EditorApplication.update+=Tick;Application.logMessageReceived+=(m,s,t)=>{if(Run&&(t==LogType.Error||t==LogType.Exception||t==LogType.Assert)){File.AppendAllText(Report,"ERROR "+m+"\n");SessionState.SetInt(P+"errors",SessionState.GetInt(P+"errors",0)+1);}};}
 static void Tick(){if(!Run&&File.Exists("Temp/camera-mouse-test.flag")&&!EditorApplication.isPlayingOrWillChangePlaymode&&!EditorApplication.isCompiling&&!EditorApplication.isUpdating){SessionState.SetBool(P+"guided",File.ReadAllText("Temp/camera-mouse-test.flag").Trim()=="guided");File.Delete("Temp/camera-mouse-test.flag");if(SceneManager.GetActiveScene().isDirty){File.WriteAllText(Report,"BLOCKED dirty scene");return;}Run=true;Stage=Index=0;SessionState.SetInt(P+"errors",0);File.WriteAllText(Report,"");EditorSceneManager.OpenScene("Assets/_Project/Scenes/Main Menu.unity");Due=EditorApplication.timeSinceStartup+6;EditorApplication.EnterPlaymode();return;}
 if(!Run||EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.timeSinceStartup<Due)return;try{if(Stage==3){if(EditorApplication.isPlayingOrWillChangePlaymode)return;EditorSceneManager.OpenScene("Assets/_Project/Scenes/PV Lab.unity");Run=false;File.AppendAllText(Report,"COMPLETE errors="+SessionState.GetInt(P+"errors",0)+"\n");return;}var manager=InteractionManager.Instance;if(!manager){Due=EditorApplication.timeSinceStartup+1;return;}if(Stage==0){manager.currentMode=Guided?ExperimentMode.Guided:ExperimentMode.Free;var launcher=Resources.FindObjectsOfTypeAll<MainMenuExperimentLauncher>().Single(l=>l.gameObject.scene==SceneManager.GetActiveScene()&&new SerializedObject(l).FindProperty("storyboardId").stringValue==ids[Index]);launcher.GetComponent<UnityEngine.UI.Button>().onClick.Invoke();Stage=1;Due=EditorApplication.timeSinceStartup+8;return;}if(Stage==1){var mover=SceneManager.GetActiveScene().GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<SmoothCameraMovement>(true)).Single();probe=mover.gameObject.AddComponent<CameraMouseProbe>();probe.Begin(mover,Guided);Stage=2;return;}if(Stage==2){if(!probe.done)return;File.AppendAllText(Report,"EXP"+(Index+1)+" "+probe.result+"\n");if(probe.result.StartsWith("FAIL"))throw new Exception(probe.result);UnityEngine.Object.Destroy(probe);Index++;if(Index==4){Stage=3;EditorApplication.ExitPlaymode();Due=EditorApplication.timeSinceStartup+2;}else{manager.ReturnToExperimentMenu();Stage=0;Due=EditorApplication.timeSinceStartup+6;}}}catch(Exception e){File.AppendAllText(Report,"FAIL "+e+"\n");SessionState.SetInt(P+"errors",SessionState.GetInt(P+"errors",0)+1);Stage=3;if(EditorApplication.isPlaying){EditorApplication.ExitPlaymode();Due=EditorApplication.timeSinceStartup+2;}else Run=false;}}
}

